'use client';

import React, { useState } from 'react';
import styles from './products.module.css';
import { Plus, Edit2, Trash2, Loader2, Image as ImageIcon } from 'lucide-react';

// Mock Products for initial load
const INITIAL_MOCK_PRODUCTS = [
    {
        _id: '1',
        name: 'Sankara Karuvadu',
        description: 'Fresh from Thoothukudi',
        originalPrice: 450,
        discountPercentage: 10,
        finalPrice: 405,
        image: 'https://images.unsplash.com/photo-1544253051-bd2e236528d2?q=80&w=400'
    },
    {
        _id: '2',
        name: 'Nethili Karuvadu',
        description: 'Sun dried anchovies',
        originalPrice: 320,
        discountPercentage: 15,
        finalPrice: 272,
        image: 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?q=80&w=400'
    }
];

export default function AdminProducts() {
    const [products, setProducts] = useState(INITIAL_MOCK_PRODUCTS);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingProduct, setEditingProduct] = useState<any>(null);
    const [formData, setFormData] = useState({
        name: '',
        description: '',
        originalPrice: '',
        discountPercentage: '',
        image: ''
    });

    const handleOpenModal = (product: any = null) => {
        if (product) {
            setEditingProduct(product);
            setFormData({
                name: product.name,
                description: product.description,
                originalPrice: product.originalPrice.toString(),
                discountPercentage: product.discountPercentage.toString(),
                image: product.image
            });
        } else {
            setEditingProduct(null);
            setFormData({ name: '', description: '', originalPrice: '', discountPercentage: '', image: '' });
        }
        setIsModalOpen(true);
    };

    const handleSave = (e: React.FormEvent) => {
        e.preventDefault();
        const finalPrice = Number(formData.originalPrice) * (1 - Number(formData.discountPercentage) / 100);

        if (editingProduct) {
            setProducts(products.map(p => p._id === editingProduct._id ? {
                ...p,
                ...formData,
                originalPrice: Number(formData.originalPrice),
                discountPercentage: Number(formData.discountPercentage),
                finalPrice
            } as any : p));
        } else {
            const newProduct = {
                _id: Date.now().toString(),
                ...formData,
                originalPrice: Number(formData.originalPrice),
                discountPercentage: Number(formData.discountPercentage),
                finalPrice
            } as any;
            setProducts([...products, newProduct]);
        }
        setIsModalOpen(false);
    };

    const handleDelete = (id: string) => {
        if (confirm('Delete this product?')) {
            setProducts(products.filter(p => p._id !== id));
        }
    };

    return (
        <div className={styles.container}>
            <div className={styles.header}>
                <h1>Manage Products</h1>
                <button className={styles.addBtn} onClick={() => handleOpenModal()}>
                    <Plus size={20} /> Add Product
                </button>
            </div>

            <div className={styles.productGrid}>
                {products.map((p) => (
                    <div key={p._id} className={styles.productCard}>
                        <div className={styles.productImg}>
                            {p.image ? <img src={p.image} alt={p.name} /> : <div className={styles.imgPlaceholder}><ImageIcon /></div>}
                        </div>
                        <div className={styles.productInfo}>
                            <h3>{p.name}</h3>
                            <p className={styles.desc}>{p.description}</p>
                            <div className={styles.priceRow}>
                                <span className={styles.finalPrice}>₹{p.finalPrice}</span>
                                <span className={styles.originalPrice}>₹{p.originalPrice}</span>
                                <span className={styles.discount}>{p.discountPercentage}% OFF</span>
                            </div>
                            <div className={styles.actions}>
                                <button className={styles.editBtn} onClick={() => handleOpenModal(p)}>
                                    <Edit2 size={16} /> Edit
                                </button>
                                <button className={styles.deleteBtn} onClick={() => handleDelete(p._id)}>
                                    <Trash2 size={16} /> Delete
                                </button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {isModalOpen && (
                <div className={styles.modalOverlay}>
                    <div className={styles.modal}>
                        <h2>{editingProduct ? 'Edit Product' : 'Add New Product'}</h2>
                        <form onSubmit={handleSave} className={styles.form}>
                            <div className={styles.inputGroup}>
                                <label>Product Name</label>
                                <input
                                    type="text"
                                    value={formData.name}
                                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                    required
                                />
                            </div>
                            <div className={styles.inputGroup}>
                                <label>Description</label>
                                <textarea
                                    value={formData.description}
                                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                    required
                                />
                            </div>
                            <div className={styles.row}>
                                <div className={styles.inputGroup}>
                                    <label>Original Price (₹)</label>
                                    <input
                                        type="number"
                                        value={formData.originalPrice}
                                        onChange={(e) => setFormData({ ...formData, originalPrice: e.target.value })}
                                        required
                                    />
                                </div>
                                <div className={styles.inputGroup}>
                                    <label>Discount (%)</label>
                                    <input
                                        type="number"
                                        value={formData.discountPercentage}
                                        onChange={(e) => setFormData({ ...formData, discountPercentage: e.target.value })}
                                        required
                                    />
                                </div>
                            </div>
                            <div className={styles.inputGroup}>
                                <label>Image URL</label>
                                <input
                                    type="text"
                                    value={formData.image}
                                    onChange={(e) => setFormData({ ...formData, image: e.target.value })}
                                    placeholder="https://images.unsplash.com/..."
                                />
                            </div>
                            <div className={styles.formActions}>
                                <button type="button" className={styles.cancelBtn} onClick={() => setIsModalOpen(false)}>Cancel</button>
                                <button type="submit" className={styles.saveBtn}>Save Product</button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}
